item.command:
/bin/bash -lc "python - <<'PY'
import os,requests
cid='4b3afab932dd862d'
with open(os.environ['GALAXY_API_KEY_FILE']) as f:k=f.read().strip()
for endpoint in ['dataset_collections/'+cid,'dataset_collections/'+cid+'/contents']:
 r=requests.get('https://usegalaxy.org/api/'+endpoint,headers={'x-api-key':k},timeout=120)
 print(endpoint,r.status_code)
 try:
  j=r.json()
  print(type(j).__name__, list(j)[:20] if isinstance(j,dict) else len(j))
  if isinstance(j,list):
   for e in j[:10]: print(e.get('element_identifier'),e.get('object',{}).get('id'),e.get('object',{}).get('name'),e.get('object',{}).get('extension'))
 except Exception: print(r.text[:500])
PY"

