item.command:
/bin/bash -lc "python - <<'PY'
import xlrd,collections
s=xlrd.open_workbook('inputs/pone.0150501.s002.xls',on_demand=True).sheet_by_name('RAW DATA')
ids=[str(s.cell_value(i,0)) for i in range(2,s.nrows)]
print('features',len(ids),'unique',len(set(ids)),'duplicates',[x for x,c in collections.Counter(ids).items() if c>1])
missing=[]
for i in range(2,s.nrows):
 for j in range(1,s.ncols):
  if s.cell_value(i,j)=='' or s.cell_type(i,j) in (xlrd.XL_CELL_EMPTY,xlrd.XL_CELL_BLANK): missing.append((i+1,j+1))
print('missing_values',len(missing))
print('last_rows')
for i in range(s.nrows-3,s.nrows): print(i+1,repr(s.row_values(i)[:3]))
PY"

